import Foundation

enum BatteryCareText: Int, CaseIterable {
    case title, description, lower, upper, heat, resumeTemperature, autoDischarge, save, install, approve
    case test, testInfo, persistentInfo, system, discharge, topUp, calibration, cancel, resume, schedules
    case add, remove, when, repetition, timeZone, missed, target, evidence, charging, holding
    case cooling, fault, paused, sleeping, unavailable, recovery, conflict, calibrationInfo, qualifying, enabled
    case actual, helper, busy, once, daily, weekdays, weekly, biweekly, monthly, chargePhase, dischargePhase, rechargePhase, holdPhase
    case systemStatus, batteryPower
}

struct BatteryCareStrings: CustomReflectable {
    let values: [String]
    var customMirror: Mirror {
        let fields = BatteryCareText.allCases.map { (String(describing: $0), self[$0]) }
        return Mirror(self, children: fields, displayStyle: .struct)
    }
    subscript(_ key: BatteryCareText) -> String { values[key.rawValue] }

    func reason(_ reason: BatteryReason) -> String {
        switch reason {
        case .system: return self[.systemStatus]
        case .unplugged: return self[.batteryPower]
        case .charging: return self[.charging]
        case .holding: return self[.holding]
        case .discharging: return self[.discharge]
        case .heat, .cooling: return self[.cooling]
        case .topUp: return self[.topUp]
        case .calibration: return self[.calibration]
        case .paused: return self[.paused]
        case .sleeping: return self[.sleeping]
        case .qualifying: return self[.qualifying]
        case .recovery: return self[.recovery]
        case .unavailable, .helperUnavailable: return self[.unavailable]
        case .conflict: return self[.conflict]
        case .busy: return self[.busy]
        default: return self[.fault]
        }
    }

    func action(_ action: BatteryScheduleAction) -> String {
        switch action {
        case .limit: return self[.upper]
        case .topUp: return self[.topUp]
        case .discharge: return self[.discharge]
        case .calibrate: return self[.calibration]
        case .system: return self[.system]
        }
    }

    func repetition(_ value: BatteryRepeat) -> String {
        self[[.once, .daily, .weekdays, .weekly, .biweekly, .monthly][BatteryRepeat.allCases.firstIndex(of: value)!]]
    }

    func phase(_ value: BatteryCalibrationPhase) -> String {
        switch value {
        case .charge: return self[.chargePhase]
        case .discharge: return self[.dischargePhase]
        case .recharge: return self[.rechargePhase]
        case .hold: return self[.holdPhase]
        }
    }
}

extension FeatureStrings {
    static func batteryCare(_ language: AppLanguage) -> BatteryCareStrings {
        BatteryCareStrings(values: BatteryCareTranslations.rows[language]!.components(separatedBy: "|"))
    }
}

